#include <bits/stdc++.h>
using namespace std;using B=bitset<512>;struct N{bool fixed;B s;int d;vector<int> pre,nxt,regs;};vector<N>a;vector<B>hyper(512);long double pc[11];
int main(int argc,char**argv){ifstream in(argv[1]);int nf,nn,nr;in>>nf>>nn>>nr;vector<B>fs(nf);vector<int>dims(nf);for(int f=0;f<nf;f++){int n,x;in>>n;dims[f]=round(log2(n));while(n--){in>>x;fs[f][x]=1;}}a.resize(nn);vector<int>last(nr,-1);for(int i=0;i<nn;i++){int fixed,f,k;in>>fixed>>f>>k;auto &n=a[i];n.fixed=fixed;n.s=fs[f];n.d=dims[f];while(k--){int r;in>>r;n.regs.push_back(r);n.pre.push_back(last[r]);n.nxt.push_back(-1);if(last[r]>=0){auto&p=a[last[r]];int j=find(p.regs.begin(),p.regs.end(),r)-p.regs.begin();p.nxt[j]=i;}last[r]=i;}}
for(int v=1;v<512;v++)for(int x=0;x<512;x++)if(!(__builtin_popcount(v&x)%2))hyper[v][x]=1;for(int d=1;d<11;d++)pc[d]=powl(d,1-.001594L);vector<int>mark(nn,0);int stamp=0;long long cases=0,feasible=0;ofstream out(argv[2]);out<<"{\"passes\":[";bool first=true;
for(int round=0;round<80;round++){long double best=-1e-13;vector<int>bst;int bv=0,bs=0;for(int sign:{1,-1})for(int v=1;v<512;v++){vector<char>active(nn);for(int i=0;i<nn;i++)active[i]=sign==1?!a[i].s[v]:(a[i].s&~hyper[v]).any();for(int seed=0;seed<nn;seed++)if(active[seed]&&!a[seed].fixed){cases++;stamp++;vector<int>q{seed};mark[seed]=stamp;bool bad=false;for(int pos=0;pos<(int)q.size();pos++){int i=q[pos];const auto &adj=sign==1?a[i].nxt:a[i].pre;for(int j:adj)if(j>=0&&active[j]&&mark[j]!=stamp){if(a[j].fixed){bad=true;break;}mark[j]=stamp;q.push_back(j);}if(bad)break;}if(bad)continue;feasible++;long double d=0;for(int i:q){for(int j:a[i].pre)if(j>=0&&mark[j]!=stamp){int r=a[i].d-a[j].d;assert(r+sign>=0);d+=pc[r+sign]-pc[r];}for(int j:a[i].nxt)if(j>=0&&mark[j]!=stamp){int r=a[j].d-a[i].d;assert(r-sign>=0);d+=pc[r-sign]-pc[r];}}if(d<best){best=d;bst=q;bv=v;bs=sign;}}}
cerr<<"round "<<round<<" delta "<<setprecision(18)<<best<<" size "<<bst.size()<<" v "<<bv<<" sign "<<bs<<" cases "<<cases<<" feasible "<<feasible<<"\n";if(bst.empty())break;if(!first)out<<",";first=false;out<<"{\"v\":"<<bv<<",\"sign\":"<<bs<<",\"nodes\":[";for(int k=0;k<(int)bst.size();k++){int i=bst[k];if(k)out<<",";out<<i;if(bs==1){B old=a[i].s;for(int x=0;x<512;x++)if(old[x])a[i].s[x^bv]=1;}else a[i].s&=hyper[bv];a[i].d+=bs;}out<<"]}";out.flush();}
out<<"],\"screened\":"<<cases<<",\"feasible\":"<<feasible<<"}\n";}
